--- a/app/globals.css
+++ b/app/globals.css
@@ -119,3 +119,78 @@ h1 {
     opacity: 0.5;
   }
 }
+
+/* The page and the selected product image have their own transition layers. */
+::view-transition-old(root),
+::view-transition-new(root) {
+  animation: none;
+}
+
+@media (prefers-reduced-motion: no-preference) {
+  ::view-transition-old(.page-exit-forward) {
+    animation: page-out-left 260ms ease-in both;
+  }
+
+  ::view-transition-new(.page-enter-forward) {
+    animation: page-in-right 320ms ease-out both;
+  }
+
+  ::view-transition-old(.page-exit-backward) {
+    animation: page-out-right 260ms ease-in both;
+  }
+
+  ::view-transition-new(.page-enter-backward) {
+    animation: page-in-left 320ms ease-out both;
+  }
+
+  ::view-transition-group(.product-image-morph) {
+    animation-duration: 420ms;
+    animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
+  }
+
+  ::view-transition-old(.loading-reveal) {
+    animation: fade-out 150ms ease-in both;
+  }
+
+  ::view-transition-new(.loading-reveal) {
+    animation: fade-in 260ms ease-out both;
+  }
+}
+
+@keyframes page-out-left {
+  to { opacity: 0; transform: translateX(-5%); }
+}
+
+@keyframes page-in-right {
+  from { opacity: 0; transform: translateX(5%); }
+}
+
+@keyframes page-out-right {
+  to { opacity: 0; transform: translateX(5%); }
+}
+
+@keyframes page-in-left {
+  from { opacity: 0; transform: translateX(-5%); }
+}
+
+@keyframes fade-out {
+  to { opacity: 0; }
+}
+
+@keyframes fade-in {
+  from { opacity: 0; }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .skeleton-image,
+  .skeleton-text {
+    animation: none;
+  }
+
+  ::view-transition-group(*),
+  ::view-transition-old(*),
+  ::view-transition-new(*) {
+    animation-duration: 0.01ms !important;
+    animation-delay: 0ms !important;
+  }
+}
